/**
 * Twproject REST API (V1).
 *
 * Docs: https://twproject.com/support/api-documentation/ (the command and
 * object reference is the `schema` object embedded in that page; its response
 * examples are https://twproject.com/support/api/returnSamples.json).
 *
 * Twproject is self-hosted: "The API call is a HTTP JSON POST call" to
 * `https://[your_server_url]/API/V1/`, so every connection supplies its own
 * server URL (`credentials.extra.serverUrl`).
 *
 * Authentication: the common request parameter `APIKey`, "generated by every
 * Twproject enabled user. The API will operate with this user privileges."
 *
 * Request: `{ command, object, APIKey, ...additionalParameters }`.
 *   get:  `id` (integer, required), `full` (boolean)
 *   list: `filters`, `pageSize`, `page`, `orderBy`
 * Response: `{ ok, errors?, messagesFromController?, object? }` for `get`, and
 * `{ ok, objects?, hasMore? }` for `list`.
 */

/** API path appended to the customer's server URL. */
export const API_PATH = '/API/V1/'

/**
 * `pageSize` sent when a caller gives no limit. The docs name no default or
 * maximum for `pageSize` (its sample value is 20), so a caller's limit is
 * always sent as given.
 */
export const DEFAULT_PAGE_SIZE = 50

/** Where users generate their API key. */
export const TOKEN_HELP_URL = 'https://twproject.com/support/api-documentation/'
